    text(body,"LogTitle","ЛОГИ",15,166,310,18,10)
    local scroll=make("ScrollingFrame",{Name="LogPanel",Position=UDim2.fromOffset(15,188),Size=UDim2.fromOffset(310,130),
        BackgroundColor3=rgb(113,71,157),BackgroundTransparency=.15,BorderSizePixel=0,ScrollBarThickness=3,
        AutomaticCanvasSize=Enum.AutomaticSize.Y,CanvasSize=UDim2.new()},body);round(scroll,10)
    local logs=make("TextLabel",{Name="LogText",Position=UDim2.fromOffset(8,6),Size=UDim2.new(1,-22,0,0),
        AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,Font=Enum.Font.Code,TextSize=11,
        TextColor3=rgb(255,245,255),TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
        TextWrapped=true,Text="",RichText=false},scroll)
    local credit=text(body,"Credit","By: Probothotspot",15,327,310,16,10)
    credit.TextXAlignment=Enum.TextXAlignment.Center
    local resize=button("Resize","↘",313,375,22,22)
    resize.TextSize=17;resize.BackgroundTransparency=.25
    function self:log(message)
        if self.Destroyed then return end
        self.Lines[#self.Lines+1]=os.date("%H:%M:%S").."  "..tostring(message)
        if #self.Lines>50 then table.remove(self.Lines,1) end
        logs.Text=table.concat(self.Lines,"\n")
        self.LastMessage=tostring(message)
        self.State.Text=self.LastMessage;self.LastShownState=self.LastMessage
    end
    function self:update(app,hopper,actions)
        if self.Destroyed then return end
        if self.AutoShown~=app.Auto then
            self.AutoShown=app.Auto
            self.AutoButton.Text=app.Auto and "Авто: ON" or "Авто: OFF"
            local state=self.Buttons[self.AutoButton]
            state.Base=app.Auto and rgb(185,120,236) or rgb(161,106,218);state.Paint()
        end
        local hop=hopper and hopper.Enabled or false
        if self.HopShown~=hop then self.HopShown=hop;self.HopButton.Text=hop and "Смена серверов: ON" or "Смена серверов: OFF" end
        if self.BusyShown~=app.Busy then self.BusyShown=app.Busy;self.TeleportButton.Text=app.Busy and "Выполняется…" or "Телепорт" end
        local state=actions and not actions.Ready and ("Индексация в фоне: "..actions.Scanned.." объектов") or self.LastMessage or "Ожидание"
        if self.LastShownState~=state then self.LastShownState=state;self.State.Text=state end
    end
    function self:clickVisibility(show)
        if not self.Destroyed then
            gui.Enabled=show
            if show and not self.Closing then window.GroupTransparency=.2;animate(window,"fade",{GroupTransparency=0},.16) end
        end
    end
    local function fit(smooth)
        local area=safe.AbsoluteSize
        if area.X<=0 or area.Y<=0 then return end
        local h=self.Collapsed and 46 or 402
        local target=math.max(.1,math.min(self.UserScale,(area.X-16)/340,(area.Y-16)/h))
        if smooth then animate(scale,"resize",{Scale=target},.08)
        else
            local channels=self.Motion[scale];if channels and channels.resize then channels.resize:Cancel() end
            scale.Scale=target
        end
        local x=window.Position.X.Scale*area.X+window.Position.X.Offset
        local y=window.Position.Y.Scale*area.Y+window.Position.Y.Offset
        window.Position=UDim2.fromOffset(math.clamp(x,0,math.max(0,area.X-340*target)),
            math.clamp(y,0,math.max(0,area.Y-h*target)))
    end
    register(safe:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() fit(false) end))
    register(collapse.Activated:Connect(function()
        if self.Closing then return end
        self.Collapsed=not self.Collapsed;body.Visible=true;resize.Visible=not self.Collapsed
        animate(body,"fade",{GroupTransparency=self.Collapsed and 1 or 0},.16)
        animate(window,"height",{Size=UDim2.fromOffset(340,self.Collapsed and 46 or 402)},.25)
        self.CollapseDue=os.clock()+.26
        collapse.Text=self.Collapsed and "+" or "−";fit(true)
    end))
    local drag,pointer,origin,resizing
    register(title.InputBegan:Connect(function(e)
        if not self.Closing and (e.UserInputType==Enum.UserInputType.MouseButton1 or e.UserInputType==Enum.UserInputType.Touch) then
            drag,pointer,origin=e,e.Position,window.Position
        end
    end))
    register(resize.InputBegan:Connect(function(e)
        if not self.Collapsed and not self.Closing and (e.UserInputType==Enum.UserInputType.MouseButton1 or e.UserInputType==Enum.UserInputType.Touch) then
            resizing={Input=e,Pointer=e.Position,Scale=scale.Scale};drag=nil
        end
    end))
    register(input.InputChanged:Connect(function(e)
        if self.Closing then return end
        if resizing then
            if e~=resizing.Input and e.UserInputType~=Enum.UserInputType.MouseMovement then return end
            local delta=e.Position-resizing.Pointer
            local dx,dy=delta.X/340,delta.Y/402
            self.UserScale=math.clamp(resizing.Scale+(math.abs(dx)>math.abs(dy) and dx or dy),.65,1.6)
            fit(true);return
        end
        if not drag then return end
        if e~=drag and not (drag.UserInputType==Enum.UserInputType.MouseButton1 and e.UserInputType==Enum.UserInputType.MouseMovement) then return end
        local delta=e.Position-pointer
        window.Position=UDim2.new(origin.X.Scale,origin.X.Offset+delta.X,origin.Y.Scale,origin.Y.Offset+delta.Y);fit()
    end))
    register(input.InputEnded:Connect(function(e)
        if e==drag then drag=nil end
        if resizing and e==resizing.Input then resizing=nil end
        if e.UserInputType==Enum.UserInputType.MouseButton1 or e.UserInputType==Enum.UserInputType.Touch then
            for _,s in pairs(self.Buttons) do if s.Pressed then s.Pressed=false;s.Paint() end end
        end
    end))
    register(input.WindowFocusReleased:Connect(function()
        drag=nil;resizing=nil
        for _,s in pairs(self.Buttons) do s.Pressed=false;s.Hover=false;s.Paint() end
    end))
    function self:closeAnimated(done)
        if self.Closing or self.Destroyed then return end
        self.Closing=true;drag=nil;resizing=nil;self.CloseDone=done;self.CloseDue=os.clock()+.23
        animate(window,"fade",{GroupTransparency=1},.22)
        local p=window.Position
        animate(window,"position",{Position=UDim2.new(p.X.Scale,p.X.Offset,p.Y.Scale,p.Y.Offset+14)},.22)
    end
    register(game:GetService("RunService").Heartbeat:Connect(function()
        if self.Destroyed then return end
        if self.CollapseDue and os.clock()>=self.CollapseDue then self.CollapseDue=nil;body.Visible=not self.Collapsed end
        if self.CloseDue and os.clock()>=self.CloseDue then
            self.CloseDue=nil;local done=self.CloseDone;self.CloseDone=nil;if done then done() end
        end
    end))
    local shimmer=tween:Create(gradient,TweenInfo.new(10,Enum.EasingStyle.Linear,Enum.EasingDirection.InOut,-1),{Rotation=360})
    local creditShimmer=tween:Create(credit,TweenInfo.new(2,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),{TextColor3=rgb(219,203,235)})
    self.Tweens={shimmer,creditShimmer};shimmer:Play();creditShimmer:Play()
    self.CloseButton=close
    function self:Destroy()
        if self.Destroyed then return end
        self.Destroyed=true
        for _,t in ipairs(self.Tweens) do t:Cancel() end
        for _,channels in pairs(self.Motion) do for _,t in pairs(channels) do t:Cancel() end end
        self.Motion={};self.CloseDone=nil
        gui:Destroy()
    end
    fit(false)
    local p=window.Position;window.Position=UDim2.new(p.X.Scale,p.X.Offset,p.Y.Scale,p.Y.Offset+14)
    animate(window,"position",{Position=p},.3);animate(window,"fade",{GroupTransparency=0},.3)
    return self
end
return Gui

end)()

local ExecutorCaps = (function()
-- Executor name is a label, never proof that an API works in this installed build.
local Caps={}
function Caps.new(env)
    env=env or {};local self={Name='Unknown',Version='',Disabled={}}
    for _,key in ipairs({'identifyexecutor','getexecutorname'})do
        if type(env[key])=='function'then
            local ok,name,version=pcall(env[key])
            if ok and type(name)=='string' and #name>0 then
                self.Name=name:gsub('%c',' '):sub(1,64)
                self.Version=type(version)=='string' and version:gsub('%c',' '):sub(1,32) or '';break
            end
        end
    end
    for _,key in ipairs({'fireclickdetector','firetouchinterest','fireproximityprompt','setclipboard','writefile','isrbxactive'})do
        if type(env[key])=='function'then self[key]=env[key]end
    end
    function self:allowed(key)return not self.Disabled[key]end
    function self:reject(key,err)
        local message=tostring(err):lower()
        for _,term in ipairs({'security','permission','identity','not supported','unavailable','not implemented','capability','denied'})do
            if message:find(term,1,true)then self.Disabled[key]=tostring(err);return true end
        end
        return false
    end
    return self
end
return Caps

end)()

local InteractionMethods = (function()
local Registry={}
function Registry.new(ctx,door,scope,world,actions,caps,clock)
    clock=clock or os.clock
    local self={Stack={{Node=scope}},Scanned=0,Ready=false,Methods={},Skipped={},Targets={}}
    local counts={};local touches={}
    local function add(m)self.Methods[#self.Methods+1]=m end
    local function skip(name,reason)self.Skipped[#self.Skipped+1]={Method=name,Status='SKIP',Reason=reason}end
    local function held(release)ctx.InteractionRelease=release end
    local function touchTarget(o)
        local p=o.Parent
        if not p or not p:IsA('BasePart') or touches[p]then return end
        touches[p]=true
        if p.CanTouch~=true then skip('Touch '..p.Name,'CanTouch выключен');return end
        if caps.firetouchinterest then
            local fn=caps.firetouchinterest
            add({Id='touch:'..#self.Methods,Name='firetouchinterest / '..p.Name,API='firetouchinterest',Hold=.2,
                Begin=function()held(function()fn(ctx.Root,p,1)end);fn(ctx.Root,p,0)end})
        else skip('firetouchinterest','Функция отсутствует')end
        if p.CanCollide==false then
            local stage=ctx.Root.CFrame
            add({Id='contact:'..#self.Methods,Name='Контакт персонажем / '..p.Name,API='PhysicalContact',Hold=.25,
                Begin=function()
                    held(function()
                        local valid,why=actions:valid(ctx,door);assert(valid,why)
                        ctx.Character:PivotTo(stage*ctx.Root.CFrame:ToObjectSpace(ctx.Character:GetPivot()))
                        ctx.Root.AssemblyLinearVelocity=Vector3.zero;ctx.Root.AssemblyAngularVelocity=Vector3.zero
                    end)
                    ctx.Character:PivotTo(CFrame.new(p.Position)*ctx.Root.CFrame:ToObjectSpace(ctx.Character:GetPivot()))
                    ctx.Root.AssemblyLinearVelocity=Vector3.zero;ctx.Root.AssemblyAngularVelocity=Vector3.zero
                end})
        else skip('Контакт персонажем','Деталь имеет коллизию; контакт внутрь не выполняется')end
    end
    local function inspect(o)
        local class=o:IsA('ClickDetector') and 'ClickDetector' or o:IsA('ProximityPrompt') and 'ProximityPrompt'
            or o:IsA('TouchTransmitter') and 'TouchTransmitter'
        if not class or not o:IsDescendantOf(scope)then return end
        counts[class]=(counts[class]or 0)+1
        if counts[class]>4 then return end
        self.Targets[#self.Targets+1]=o
        if class=='TouchTransmitter'then touchTarget(o)
        elseif class=='ClickDetector'then
            if caps.fireclickdetector then
                add({Id='detector:'..#self.Methods,Name='fireclickdetector / '..o.Parent.Name,API='fireclickdetector',Hold=.05,
                    Begin=function()assert(o:IsDescendantOf(scope),'ClickDetector исчез');caps.fireclickdetector(o)end})
            else skip('fireclickdetector','Функция отсутствует')end
        else
            if o.Enabled~=true then skip('ProximityPrompt','Объект выключен');return end
            local duration=o.HoldDuration
            if type(duration)~='number' or duration<0 or duration>5 then skip('ProximityPrompt','HoldDuration вне диапазона 0–5 секунд');return end
            local function validPrompt()assert(o:IsDescendantOf(scope) and o.Enabled,'ProximityPrompt недоступен')end
            if caps.fireproximityprompt and duration==0 then
                add({Id='prompt-fire:'..#self.Methods,Name='fireproximityprompt / '..o.Name,API='fireproximityprompt',Hold=.05,
                    Begin=function()validPrompt();caps.fireproximityprompt(o)end})
            else skip('fireproximityprompt',not caps.fireproximityprompt and 'Функция отсутствует' or 'Ненулевой HoldDuration: используется штатное удержание')end
            add({Id='prompt-hold:'..#self.Methods,Name='ProximityPrompt InputHold / '..o.Name,API='Prompt.InputHold',Hold=math.max(.12,duration+.1),
                Begin=function()validPrompt();held(function()o:InputHoldEnd()end);o:InputHoldBegin()end})
            if o.KeyboardKeyCode and o.KeyboardKeyCode~=Enum.KeyCode.Unknown then
                local code=o.KeyboardKeyCode
                if ctx.Input then
                    add({Id='key-vim:'..#self.Methods,Name='Клавиша prompt / VIM / '..tostring(code),API='VIM.Key',Hold=math.max(.12,duration+.1),
                        Begin=function()validPrompt();held(function()ctx.Input:SendKeyEvent(false,code,false,game)end);ctx.Input:SendKeyEvent(true,code,false,game)end})
                end
                if ctx.Virtual then
                    add({Id='key-vi:'..#self.Methods,Name='Клавиша prompt / VirtualInput / '..tostring(code),API='VI.Key',Hold=math.max(.12,duration+.1),
                        Begin=function()validPrompt();held(function()ctx.Virtual:SendKey(false,code,false)end);ctx.Virtual:SendKey(true,code,false)end})
                end
            end
        end
    end
    local function finish()
        if not counts.ClickDetector then skip('ClickDetector','На выбранной двери нет объекта ClickDetector')end
        if not counts.ProximityPrompt then skip('ProximityPrompt','На выбранной двери нет объекта ProximityPrompt')end
        if not counts.TouchTransmitter then skip('Touch','На выбранной двери нет TouchTransmitter')end
        local function mouse(name,kind,api)
            add({Id=api..':'..kind,Name=name,API=api,Hold=.12,
                Prepare=function()
                    ctx.Method={Name=name,Kind=kind}
                    local point,visible
                    if kind=='viewport'then point,visible=ctx.Camera:WorldToViewportPoint(door.Position)
                    else point,visible=ctx.Camera:WorldToScreenPoint(door.Position)end
                    assert(visible and point.Z>0,'Дверь вне экрана')
                    ctx.Mouse={X=math.floor(point.X+.5),Y=math.floor(point.Y+.5)}
                    if kind=='virtual'then ctx.Virtual:SendMousePosition(Vector2.new(ctx.Mouse.X,ctx.Mouse.Y))
                    else ctx.Input:SendMouseMoveEvent(ctx.Mouse.X,ctx.Mouse.Y,game)end
                end,
                Begin=function()actions:mouseDown(ctx,door)end})
        end
        if ctx.Virtual then mouse('VirtualInput mouse','virtual','VI.Mouse')else skip('VirtualInput','CreateVirtualInput не вернул объект')end
        if ctx.Input then mouse('VIM screen','screen','VIM.Mouse');mouse('VIM viewport','viewport','VIM.Mouse')
        else skip('VIM','Сервис недоступен')end
        self.Ready=true
    end
    function self:step()
        if self.Ready then return end
        local start=clock();local work=0
        while #self.Stack>0 and work<64 and clock()-start<.001 do
            work=work+1;local f=self.Stack[#self.Stack]
            if not f.Children then f.Children=f.Node:GetChildren();f.Index=1
            elseif f.Index>#f.Children then table.remove(self.Stack)
            else
                local o=f.Children[f.Index];f.Index=f.Index+1;self.Scanned=self.Scanned+1;inspect(o)
                if self.Scanned<512 then self.Stack[#self.Stack+1]={Node=o}else self.Stack={};break end
            end
        end
        if #self.Stack==0 then finish()end
    end
    function self:release()
        if ctx.InteractionRelease then ctx.InteractionRelease();ctx.InteractionRelease=nil end
        actions:mouseUp(ctx)
    end
    return self
end
return Registry

end)()

local MethodTest = (function()
local Test={}
function Test.start(Core,Actions,Gui,Feedback,Caps,Registry)
    local player=game:GetService('Players').LocalPlayer;assert(player,'Client player required')
    local env=_G
    if type(getgenv)=='function'then local ok,v=pcall(getgenv);if ok and type(v)=='table'then env=v end end
    local key='AutoCandyMethodTest'
    if type(env[key])=='table' and type(env[key].Destroy)=='function'then env[key]:Destroy()end
    local functions={identifyexecutor=identifyexecutor,getexecutorname=getexecutorname,
        fireclickdetector=fireclickdetector,firetouchinterest=firetouchinterest,fireproximityprompt=fireproximityprompt,
        setclipboard=setclipboard,writefile=writefile,isrbxactive=isrbxactive}
    for name in pairs({identifyexecutor=true,getexecutorname=true,fireclickdetector=true,firetouchinterest=true,
        fireproximityprompt=true,setclipboard=true,writefile=true,isrbxactive=true})do
        if type(functions[name])~='function' and type(env[name])=='function'then functions[name]=env[name]end
    end
    local caps=Caps.new(functions)
    local self={Version='1.0.0',Busy=false,Phase='idle',Caps=caps,Connections={},Report={Executor=caps.Name,Results={}}}
    local view,actions,ctx,door,registry,hud,label,active,result
    local function register(c)self.Connections[#self.Connections+1]=c;return c end
    local function log(s)if view and not view.Destroyed then view:log(s)end end
    local function reportJSON()
        local ok,value=pcall(function()return game:GetService('HttpService'):JSONEncode(self.Report)end)
        return ok and value or table.concat(view.Lines,'\n'),ok
    end
    local function save()
        if caps.writefile then
            local data,encoded=reportJSON()
            if not encoded then log('JSON недоступен; текстовый отчёт можно скопировать');return end
            local ok,err=pcall(caps.writefile,'AutoCandyMethods-v1.json',data)
            if not ok then log('Сохранение отчёта: '..tostring(err))end
        end
    end
    local function record(status,detail)
        result.Status=status;result.Detail=tostring(detail or '')
        if not result.Recorded then result.Recorded=true;self.Report.Results[#self.Report.Results+1]=result end
        log(result.Method..' — '..status..(detail and (': '..tostring(detail))or ''))
    end
    function self:finish(reason)
        if not self.Busy then return end
        self.Busy=false;self.Phase='idle'
        if result and not result.Recorded then record('CANCELLED',reason)end
        local old=ctx;ctx=nil
        local released,releaseError=true,nil
        if registry then released,releaseError=pcall(registry.release,registry)end
        local restored,restoreError=pcall(actions.restore,actions,old)
        if old and old.OtherGui and old.OtherGui.Parent then old.OtherGui.Enabled=old.OtherEnabled end
        if old and old.PixelGui and old.PixelGui.Parent then old.PixelGui.Enabled=old.PixelEnabled end
        hud.Enabled=false
        self.Report.FinishedAt=os.time();self.Report.Outcome=reason or 'FINISHED'
        self.Report.Released=released;self.Report.Restored=restored
        if not released then log('Освобождение ввода: '..tostring(releaseError))end
        if not restored then log('Восстановление: '..tostring(restoreError))end
        log(reason or 'Проверка завершена')
        log(self.Report.Best and ('Стук замечен после: '..self.Report.Best) or 'Подтверждённого стука нет')
        save();active=nil;result=nil
    end
    local function nextMethod()
        local released,err=pcall(registry.release,registry)
        if not released then self:finish('Не удалось освободить ввод: '..tostring(err));return end
        self.Index=(self.Index or 0)+1
        active=registry.Methods[self.Index];result=nil
        if not active then self:finish('Все доступные методы проверены');return end
        if not caps:allowed(active.API)then
            self.Report.Results[#self.Report.Results+1]={Method=active.Name,API=active.API,Status='SKIP',Reason='API ранее отказал: '..caps.Disabled[active.API]}
            log('Пропуск '..active.Name..': API уже отказал')
            active=nil;self.Phase='next';self.Due=os.clock()+.05;return
        end
        result={Method=active.Name,API=active.API,Status='PENDING'}
        label.Text=self.Index..'/'..#registry.Methods..' | '..active.Name
        log('Проверка '..self.Index..'/'..#registry.Methods..': '..active.Name)
        self.Phase='prepare';self.Due=os.clock()+.25
    end
    function self:Start()
        if self.Busy or self.Destroyed or view.Closing then return end
        if self.InTick then log('Предыдущий вызов ещё не завершён');return end
        if not actions.Ready then log('Индекс строится в фоне; повтори через секунду');return end
        local best,distance
        for _,p in ipairs(actions:doors())do local d=actions:distance(p);if d and(not distance or d<distance)then best,distance=p,d end end
        if not best then log('Нет существующих объектов DoorInnerTouch / Door');return end
        for _,oldKey in ipairs({'AutoCandyPixelTest'})do
            local previous=env[oldKey]
            if type(previous)=='table' and previous.Busy and type(previous.finish)=='function'then previous:finish('Запущен тест методов')end
        end
        local main=env.SlapBattlesAutoCandy
        if type(main)=='table'then
            if main.Hopper then main.Hopper:setEnabled(false)end
            if main.App then main.App:setAuto(false)end
        end
        local ok,captured=pcall(actions.capture,actions)
        if not ok then log('Запуск: '..tostring(captured));return end
        ctx=captured;door=best;registry=nil;active=nil;result=nil;self.Index=0;self.Busy=true
        if type(main)=='table' and main.Gui and main.Gui.Parent then ctx.OtherGui=main.Gui;ctx.OtherEnabled=main.Gui.Enabled;main.Gui.Enabled=false end
        local pixel=env.AutoCandyPixelTest
        if type(pixel)=='table' and pixel.Gui and pixel.Gui.Parent then ctx.PixelGui=pixel.Gui;ctx.PixelEnabled=pixel.Gui.Enabled;pixel.Gui.Enabled=false end
        self.Report={Executor=caps.Name,ExecutorVersion=caps.Version,StartedAt=os.time(),PlaceId=game.PlaceId,
            Door=door:GetFullName(),Results={},RewardConfirmed=false}
        local moved,why=pcall(actions.approach,actions,ctx,door)
        if not moved then self:finish('ТП: '..tostring(why));return end
        self.Phase='settle';self.Due=os.clock()+.35;self.Deadline=os.clock()+90
        log('Исполнитель: '..caps.Name..'. Совместимость проверяется вызовом API')
    end
    function self:Destroy()
        if self.Destroyed then return end
        self:finish('Остановка');self.Destroyed=true
        if actions then actions:Destroy()end
        for _,c in ipairs(self.Connections)do c:Disconnect()end
        self.Connections={}
        if hud then hud:Destroy()end
        if view then view:Destroy()end
        if env[key]==self then env[key]=nil end
    end
    env[key]=self
    local ok,problem=pcall(function()
        view=Gui.mount(player,register);self.Gui=view.Gui;view.Gui.Name='AutoCandyMethodTestGUI'
        view.Gui:FindFirstChild('Title',true).Text='Door Test | '..caps.Name:sub(1,18)
        view.Gui:FindFirstChild('Title',true).TextSize=15
        view.Gui:FindFirstChild('Subtitle',true).Text='Объекты двери → методы → проверка стука'
        view.AutoButton.Text='Тест методов';view.TeleportButton.Text='Стоп';view.HopButton.Text='Копировать отчёт'
        hud=Instance.new('ScreenGui');hud.Name='DoorMethodHUD';hud.ResetOnSpawn=false;hud.DisplayOrder=1001
        hud.IgnoreGuiInset=true;hud.Enabled=false;hud.Parent=player:WaitForChild('PlayerGui')
        label=Instance.new('TextLabel');label.Size=UDim2.fromOffset(300,27);label.Position=UDim2.fromOffset(10,52)
        label.BackgroundColor3=Color3.fromRGB(137,83,196);label.TextColor3=Color3.fromRGB(255,247,255)
        label.TextSize=12;label.TextWrapped=true;label.Font=Enum.Font.Gotham;label.Parent=hud
        local stop=Instance.new('TextButton');stop.Name='Stop';stop.Text='Стоп / вернуть персонажа'
        stop.Size=UDim2.fromOffset(300,27);stop.Position=UDim2.fromOffset(10,80)
        stop.BackgroundColor3=Color3.fromRGB(161,106,218);stop.TextColor3=Color3.fromRGB(255,247,255)
        stop.Font=Enum.Font.Gotham;stop.TextSize=12;stop.Parent=hud
        actions=Actions.new(player,workspace,Core,register,log,function(show)view:clickVisibility(show)end)
        register(view.AutoButton.Activated:Connect(function()self:Start()end))
        register(view.TeleportButton.Activated:Connect(function()self:finish('Остановлено пользователем')end))
        register(stop.Activated:Connect(function()self:finish('Остановлено пользователем')end))
        register(view.HopButton.Activated:Connect(function()
            if caps.setclipboard then local data=reportJSON();local copied,err=pcall(caps.setclipboard,data);log(copied and 'Отчёт скопирован' or tostring(err))
            else log('setclipboard отсутствует')end
        end))
        register(view.CloseButton.Activated:Connect(function()
            if view.Closing then return end
            self:finish('Закрытие');view:closeAnimated(function()self:Destroy()end)
        end))
        register(view.Gui.Destroying:Connect(function()self:Destroy()end))
        register(game:GetService('RunService').Heartbeat:Connect(function()
            if self.Destroyed or self.InTick then return end
            self.InTick=true
            local worked,why=pcall(function()
                actions:serviceIndex();if not self.Busy then return end
                local valid,reason=actions:valid(ctx,door);assert(valid,reason)
                if os.clock()>self.Deadline then self:finish('Лимит времени теста');return end
                if ctx.Monitor then
                    ctx.Monitor:step()
                    if result and not result.Recorded then
                        local sound=ctx.Monitor.Result
                        if sound then
                            record('KNOCK',sound.Id);self.Report.Best=active.Name;self.Report.SoundId=sound.Id
                            self:finish('Обнаружен локальный стук; повтор остановлен');return
                        end
                    end
                end
                if os.clock()<self.Due then return end
                if self.Phase=='settle'then
                    actions:aim(ctx,door)
                    local scope=door.Parent;while scope and scope~=workspace and scope.Name:lower()~='door'do scope=scope.Parent end
                    assert(scope and scope~=workspace,'Контейнер Door исчез')
                    ctx.Scope=scope;ctx.Monitor=Feedback.new(scope)
                    registry=Registry.new(ctx,door,scope,workspace,actions,caps)
                    self.Phase='scan';self.Due=os.clock()+.05
                elseif self.Phase=='scan'then
                    registry:step()
                    if not registry.Ready or not ctx.Monitor.Ready then return end
                    for _,row in ipairs(registry.Skipped)do self.Report.Results[#self.Report.Results+1]=row;log('Пропуск '..row.Method..': '..row.Reason)end
                    log('Методов для проверки: '..#registry.Methods);hud.Enabled=true;nextMethod()
                elseif self.Phase=='next'then nextMethod()
                elseif self.Phase=='prepare'then
                    if caps.isrbxactive then assert(caps.isrbxactive(),'Окно Roblox не в фокусе')end
                    local prepared,err=pcall(function()if active.Prepare then active.Prepare()end end)
                    if not self.Busy then return end
                    if not prepared then caps:reject(active.API,err);record('ERROR',err);nextMethod();return end
                    self.Phase='begin';self.Due=os.clock()+.15
                elseif self.Phase=='begin'then
                    ctx.Monitor:arm()
                    ctx.Monitor.Until=os.clock()+active.Hold+2.1
                    local oldRegistry=registry
                    local called,err=pcall(active.Begin)
                    if not self.Busy then pcall(oldRegistry.release,oldRegistry);return end
                    if not called then caps:reject(active.API,err);record('ERROR',err);nextMethod();return end
                    result.CallReturned=true;log('API вызван без ошибки; ожидаю ответ двери')
                    self.Phase='held';self.Due=os.clock()+active.Hold
                elseif self.Phase=='held'then
                    registry:release();self.Phase='listen';self.Due=os.clock()+1.8
                elseif self.Phase=='listen'then
                    local sound=ctx.Monitor.Candidate
                    if sound then record('LOCAL_SOUND',sound.Name..' | '..sound.Id);self:finish('Тип звука неизвестен; повтор остановлен')
                    else record('NO_RESPONSE','Наблюдаемого стука нет');nextMethod()end
                end
            end)
            self.InTick=false
            if not worked then self:finish('Ошибка: '..tostring(why));log(tostring(why))end
        end))
        log('Door Methods готов | '..caps.Name)
        log('Нет обещанного списка по бренду: API и объекты проверяются в этой сессии')
    end)
    if not ok then self:Destroy();error(problem)end
    return self
end
return Test

end)()

return MethodTest.start(Core, Actions, Gui, Feedback, ExecutorCaps, InteractionMethods)
